"use client";

import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "@/lib/utils";

// Segmented Control: generated by UIX from the design system. Same variants and sizes as the Figma component.

const segmentedVariants = cva(
  "inline-flex items-stretch p-1 gap-1 bg-muted rounded-md",
  {
    variants: {
      size: {
        sm: "text-label-small [&_label>span]:h-6 [&_label>span]:px-3",
        md: "text-label-medium [&_label>span]:h-8 [&_label>span]:px-4",
      },
    },
    defaultVariants: {
      size: "md",
    },
  },
);

export interface SegmentedOption {
  value: string;
  label: React.ReactNode;
  disabled?: boolean;
}

export interface SegmentedProps
  extends Omit<React.HTMLAttributes<HTMLDivElement>, "onChange" | "defaultValue">,
    VariantProps<typeof segmentedVariants> {
  options: SegmentedOption[];
  /** Selected value (controlled). */
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  /** Shared name of the radio inputs (defaults to a generated id). */
  name?: string;
}

const Segmented = React.forwardRef<HTMLDivElement, SegmentedProps>(
  ({ className, size, options, value, defaultValue, onValueChange, name, ...props }, ref) => {
    const autoName = React.useId();
    const [inner, setInner] = React.useState(defaultValue ?? options[0]?.value);
    const current = value ?? inner;
    return (
      <div data-slot="segmented" data-kind="track" ref={ref} role="radiogroup" className={cn(segmentedVariants({ size }), className)} {...props}>
        {options.map((option) => (
          <label key={option.value} className="relative flex flex-1">
            <input type="radio" name={name ?? autoName} value={option.value} disabled={option.disabled} checked={current === option.value} onChange={() => {
              setInner(option.value);
              onValueChange?.(option.value);
            }} className="peer sr-only" />
            <span data-kind={current === option.value ? "chip" : void 0} className="flex cursor-pointer items-center justify-center whitespace-nowrap rounded-[inherit] transition-colors text-fg-secondary peer-checked:shadow-sm peer-checked:bg-surface peer-checked:text-fg-primary peer-focus-visible:ring-3 peer-focus-visible:ring-line-focus peer-disabled:cursor-not-allowed peer-disabled:text-fg-disabled">{option.label}</span>
          </label>
        ))}
      </div>
    );
  },
);
Segmented.displayName = "Segmented";

export { Segmented, segmentedVariants };
